@intent_handler("previous_picture.intent", requires_context=["SlideShow"])
def handle_prev(self, message=None):
    self.pic_idx -= 1
    if self.pic_idx < 0:
        self.pic_idx = 0
        self.speak_dialog("no_more_pictures")
    else:
        self.acknowledge()
        image = self.picture_list[self.pic_idx]
        self.gui.show_image(image)

